import { Check } from '@phosphor-icons/react';
import clsx from 'clsx';
import { ReferenceDetails } from '@/library/ReferenceDetails';
import { ReferenceImage } from '@/library/ReferenceImage';
import { CopyReferenceButton } from '@/library/CopyReferenceButton';
import type { ReferenceStep } from '@/library/referenceStep';
import type {
  DesignLibraryReference,
  DesignLibrarySource,
} from '@rivet/core/types/design-library';

interface ReferenceCardProps {
  profileId: string;
  reference: DesignLibraryReference;
  sources: DesignLibrarySource[];
  referenceKey: string;
  isSelected: boolean;
  isSelectionDisabled: boolean;
  onSelect: () => void;
  isOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  onStep?: (step: ReferenceStep) => void;
}

const HOVER_VISIBILITY =
  'opacity-0 group-hover/card:opacity-100 group-focus-within/card:opacity-100 [@media(hover:none)]:opacity-100';
const HOVER_ACTIONS =
  'pointer-events-none group-hover/card:pointer-events-auto group-focus-within/card:pointer-events-auto [@media(hover:none)]:pointer-events-auto';

export const ReferenceCard = ({
  profileId,
  reference,
  sources,
  referenceKey,
  isSelected,
  isSelectionDisabled,
  onSelect,
  isOpen,
  onOpenChange,
  onStep,
}: ReferenceCardProps) => {
  const title = reference.title || 'Untitled reference';
  const media = reference.media[0];
  return (
    <div className="group/card relative">
      <ReferenceDetails
        profileId={profileId}
        reference={reference}
        sources={sources}
        referenceKey={referenceKey}
        isOpen={isOpen}
        onOpenChange={onOpenChange}
        onStep={onStep}
      >
        <button
          aria-label={`Inspect ${title}`}
          className="focus-visible:border-muted-foreground block w-full overflow-hidden border border-transparent text-left focus-visible:outline-hidden transition-colors"
        >
          {media ? (
            <ReferenceImage
              key={media.hash}
              profileId={profileId}
              referenceId={reference.id}
              hash={media.hash}
              title={title}
            />
          ) : (
            <div className="border-border bg-surface-2 min-h-44 border p-5 pb-14">
              <p className="text-soft-foreground text-sm font-medium">
                {title}
              </p>
              <p className="text-muted-foreground mt-3 line-clamp-3 text-xs leading-5">
                {reference.observation?.description ?? reference.text}
              </p>
            </div>
          )}
        </button>
      </ReferenceDetails>
      <div
        aria-hidden
        className={clsx(
          'pointer-events-none absolute inset-0 bg-media-dim',
          HOVER_VISIBILITY,
        )}
      />
      <div
        className={clsx(
          'absolute inset-x-0 bottom-0 z-10 flex items-center justify-between gap-2 p-2',
          isSelected ? null : HOVER_VISIBILITY,
          isSelected ? null : HOVER_ACTIONS,
        )}
      >
        <label
          className="relative shrink-0 cursor-pointer"
          title={isSelected ? 'Deselect' : 'Select'}
        >
          <input
            type="checkbox"
            aria-label={`Select ${title}`}
            checked={isSelected}
            disabled={isSelectionDisabled}
            onChange={onSelect}
            className="peer absolute inset-0 h-full w-full cursor-pointer opacity-0 focus-visible:outline-hidden disabled:cursor-default"
          />
          <span
            className={clsx(
              'peer-focus-visible:border-on-media peer-focus-visible:text-on-media flex h-7 w-7 items-center justify-center rounded-full border shadow-control transition-colors peer-disabled:opacity-40 forced-colors:peer-focus-visible:outline-2 forced-colors:peer-focus-visible:outline-offset-2 forced-colors:peer-focus-visible:outline-solid',
              isSelected
                ? 'border-primary bg-primary text-primary-foreground'
                : 'peer-enabled:peer-hover:text-on-media border-on-media-border bg-media-control text-on-media-muted peer-focus-visible:bg-media-control-focus',
            )}
          >
            <Check size={14} weight="bold" aria-hidden />
          </span>
        </label>
        <CopyReferenceButton
          key={reference.revision}
          profileId={profileId}
          referenceKeys={[referenceKey]}
          providers={[reference.provider]}
        />
      </div>
    </div>
  );
};
