import type { KeyboardEvent } from 'react';
import { isMenuOpen } from '@/utils/menuOpenRegistry';
import { isTextEntryTarget } from '@/utils/textEntryTarget';

export type ReferenceStep = -1 | 1;

const REFERENCE_STEP_KEYS = new Map<string, ReferenceStep>([
  ['ArrowLeft', -1],
  ['ArrowRight', 1],
]);

export const referenceStepFromKey = (
  event: KeyboardEvent,
): ReferenceStep | null => {
  const step = REFERENCE_STEP_KEYS.get(event.key);
  if (!step || event.defaultPrevented) return null;
  if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey)
    return null;
  if (isTextEntryTarget(event.target) || isMenuOpen()) return null;
  return step;
};
