import { CopyButton } from '@/library/CopyButton';
import { DesignReferenceRequestSchema } from '@rivet/core/types/design-library';
import type { ProfileProvider } from '@rivet/core/types/design-profile';

interface CopyReferenceButtonProps {
  profileId: string;
  referenceKeys: string[];
  providers: ProfileProvider[];
}

const copiedProvider = (providers: ProfileProvider[]) => {
  const distinct = new Set(providers);
  if (distinct.size > 1) return 'mixed';
  return [...distinct][0];
};

const referenceCommand = ({
  profileId,
  referenceKeys,
}: Pick<CopyReferenceButtonProps, 'profileId' | 'referenceKeys'>) => {
  const request = DesignReferenceRequestSchema.parse({
    profileId,
    keys: referenceKeys,
  });
  return [
    'rivet',
    'profile',
    'reference',
    request.profileId,
    ...request.keys,
  ].join(' ');
};

export const CopyReferenceButton = (props: CopyReferenceButtonProps) => {
  const label =
    props.referenceKeys.length === 1
      ? 'Copy to agent'
      : `Copy ${props.referenceKeys.length} to agent`;
  return (
    <CopyButton
      label={label}
      referenceCount={props.referenceKeys.length}
      provider={copiedProvider(props.providers)}
      onCopy={() => navigator.clipboard.writeText(referenceCommand(props))}
    />
  );
};
