import { createContext, useContext, useState, type ReactNode } from 'react';
import { createPortal } from 'react-dom';
import rivetMarkUrl from '@/assets/rivet-icon-mark.svg';

interface LibraryLayoutProps {
  navigation?: ReactNode;
  onBrowseProjects?: () => void;
  controls?: ReactNode;
  isHeaderVisible?: boolean;
  children?: ReactNode;
}

const HeaderControlsContext = createContext<HTMLDivElement | null>(null);

export const LibraryLayout = ({
  navigation,
  onBrowseProjects,
  controls,
  isHeaderVisible = true,
  children,
}: LibraryLayoutProps) => {
  const [target, setTarget] = useState<HTMLDivElement | null>(null);
  return (
    <HeaderControlsContext.Provider value={target}>
      {isHeaderVisible ? (
        <div className="grid shrink-0 grid-cols-[auto_minmax(0,1fr)] items-center gap-4 px-10 py-5 max-sm:px-5 sm:grid-cols-[auto_minmax(0,1fr)_auto]">
          <button
            onClick={onBrowseProjects}
            aria-label="Projects"
            className="hover:bg-hover focus-visible:border-muted-foreground focus-visible:bg-active -m-1 flex items-center rounded-lg border border-transparent p-[3px] transition-colors focus-visible:outline-hidden"
          >
            <img
              src={rivetMarkUrl}
              alt=""
              aria-hidden
              draggable={false}
              className="h-8 w-8"
            />
          </button>
          <div
            ref={setTarget}
            className="col-span-2 row-start-2 flex min-w-0 items-center gap-3 sm:col-span-1 sm:col-start-2 sm:row-start-1"
          >
            {controls}
          </div>
          <div className="col-start-2 row-start-1 justify-self-end sm:col-start-3">
            {navigation}
          </div>
        </div>
      ) : null}
      {children}
    </HeaderControlsContext.Provider>
  );
};

export const LibraryHeaderControls = ({
  children,
}: {
  children: ReactNode;
}) => {
  const target = useContext(HeaderControlsContext);
  return target ? createPortal(children, target) : null;
};
