import { useState, type ReactNode } from 'react';
import { useQuery } from '@tanstack/react-query';
import { usePostHog } from 'posthog-js/react';
import { useAccount } from '@/hooks/useAccount';
import { requestLibrary } from '@/library/api';
import { DesignLibraryView } from '@/library/DesignLibraryView';
import { MagnifyingGlass } from '@phosphor-icons/react';
import Button from '@/components/Button';
import TextInput from '@/components/TextInput';
import ConnectorsModal from '@/components/ConnectorsModal';
import { LibraryHeaderControls } from '@/library/LibraryLayout';
import { DesignLibrarySnapshotSchema } from '@rivet/core/types/design-library';
import { queryKeys } from '@/utils/queryKeys';

const REFRESH_INTERVAL_MS = 10_000;

export const DesignLibrary = ({
  onBrowseProjects,
  initialOpenReferenceId,
}: {
  onBrowseProjects: () => void;
  initialOpenReferenceId?: string;
}) => {
  const account = useAccount();
  const posthog = usePostHog();
  const [isSourcesOpen, setIsSourcesOpen] = useState(false);
  const isAddSourcesDisabled = !account.data?.isAuthenticated;
  const openSources = (entryPoint: 'header' | 'empty_state') => {
    if (isAddSourcesDisabled) return;
    posthog?.capture('library_sources_opened', { entry_point: entryPoint });
    setIsSourcesOpen(true);
  };
  const library = useQuery({
    queryKey: queryKeys.designLibrary(
      account.data?.userId,
      account.data?.isAuthenticated,
    ),
    queryFn: ({ signal }) =>
      requestLibrary('/profile/library', {
        schema: DesignLibrarySnapshotSchema,
        signal,
      }),
    enabled: !account.isPending,
    refetchInterval: REFRESH_INTERVAL_MS,
    gcTime: 0,
    retry: false,
  });
  const retryLibrary = () => {
    posthog?.capture('library_reference_retry');
    void library.refetch();
  };
  const header = (
    <LibraryHeaderControls>
      <TextInput
        type="search"
        leadingIcon={MagnifyingGlass}
        aria-label="Search references"
        placeholder="Search references…"
        value=""
        disabled
        containerClassName="w-64 max-sm:flex-1"
        className="text-xs"
      />
    </LibraryHeaderControls>
  );
  let content: ReactNode;
  if (library.isError && !library.data)
    content = (
      <div className="flex min-h-0 flex-1 flex-col">
        {header}
        <div className="m-auto max-w-md px-8 text-center">
          <h1 className="mb-3 text-lg font-medium">References</h1>
          <p role="alert" className="text-muted-foreground text-sm">
            {library.error.message}
          </p>
          <div className="mt-5 flex justify-center gap-3">
            <Button variant="ghost" onClick={onBrowseProjects}>
              Projects
            </Button>
          </div>
        </div>
      </div>
    );
  else if (!library.data)
    content = (
      <div className="flex min-h-0 flex-1 flex-col">
        {header}
        <p role="status" className="text-foreground-tertiary m-auto text-xs">
          Loading references…
        </p>
      </div>
    );
  else
    content = (
      <div className="flex min-h-0 flex-1 flex-col">
        {library.isError ? (
          <div
            role="alert"
            className="text-muted-foreground border-border flex items-center justify-between gap-4 border-b px-8 py-3 text-xs"
          >
            <span>Could not refresh. Showing the last saved results.</span>
            <Button variant="ghost" onClick={retryLibrary}>
              Try again
            </Button>
          </div>
        ) : null}
        <DesignLibraryView
          key={library.data.profileId}
          snapshot={library.data}
          onAddSources={() => openSources('empty_state')}
          isAddSourcesDisabled={isAddSourcesDisabled}
          initialOpenReferenceId={initialOpenReferenceId}
        />
      </div>
    );
  return (
    <>
      {content}
      <LibraryHeaderControls>
        <Button
          variant="tertiary"
          className="order-last shrink-0"
          disabled={isAddSourcesDisabled}
          onClick={() => openSources('header')}
        >
          Add sources
        </Button>
      </LibraryHeaderControls>
      <ConnectorsModal
        isOpen={isSourcesOpen}
        onClose={() => {
          posthog?.capture('library_sources_closed');
          setIsSourcesOpen(false);
        }}
        context="library"
      />
    </>
  );
};
