import type { ReactNode } from 'react';
import { usePostHog } from 'posthog-js/react';
import { ArrowUpRight, X } from '@phosphor-icons/react';
import Button from '@/components/Button';
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from '@/components/Dialog';
import { ReferenceImage } from '@/library/ReferenceImage';
import { ReferenceProviderLabel } from '@/library/ReferenceProviderLabel';
import { CopyReferenceButton } from '@/library/CopyReferenceButton';
import {
  referenceStepFromKey,
  type ReferenceStep,
} from '@/library/referenceStep';
import type {
  DesignLibraryReference,
  DesignLibrarySource,
} from '@rivet/core/types/design-library';
import type { ProfileObservation } from '@rivet/core/types/design-profile';

const EVIDENCE_HEADINGS: Record<ProfileObservation['evidence'], string> = {
  observation: 'Rivet’s analysis',
  preference: 'Your preference',
  provisional: 'Saved text, not yet analyzed',
};

interface ReferenceDetailsProps {
  profileId: string;
  reference: DesignLibraryReference;
  sources: DesignLibrarySource[];
  referenceKey: string;
  children: ReactNode;
  isOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  onStep?: (step: ReferenceStep) => void;
}

export const ReferenceDetails = ({
  profileId,
  reference,
  sources,
  referenceKey,
  children,
  isOpen,
  onOpenChange,
  onStep,
}: ReferenceDetailsProps) => {
  const posthog = usePostHog();
  const title = reference.title || 'Untitled reference';
  const originalUrl =
    reference.url && /^https?:\/\//i.test(reference.url)
      ? reference.url
      : undefined;
  return (
    <Dialog
      open={isOpen}
      onOpenChange={(isNextOpen) => {
        posthog?.capture(
          isNextOpen ? 'library_reference_opened' : 'library_reference_closed',
          { provider: reference.provider, media_count: reference.media.length },
        );
        onOpenChange?.(isNextOpen);
      }}
    >
      <DialogTrigger asChild>{children}</DialogTrigger>
      <DialogContent
        surface="librarySheet"
        className="ph-no-capture"
        data-rivet-private
        onKeyDown={(event) => {
          const step = referenceStepFromKey(event);
          if (!step || !onStep) return;
          event.preventDefault();
          onStep(step);
        }}
      >
        <header className="border-border-subtle flex items-start justify-between gap-6 border-b px-7 py-6">
          <div className="min-w-0">
            <DialogDescription className="text-muted-foreground mb-2 text-xs">
              <ReferenceProviderLabel provider={reference.provider} />
            </DialogDescription>
            <DialogTitle className="text-lg leading-snug font-medium tracking-tight break-words">
              {title}
            </DialogTitle>
          </div>
          <DialogClose asChild>
            <Button
              variant="ghost"
              size="icon-compact"
              aria-label="Close reference"
            >
              <X size={18} weight="bold" aria-hidden />
            </Button>
          </DialogClose>
        </header>
        <div className="border-border-subtle border-b px-7 py-4">
          <CopyReferenceButton
            key={reference.revision}
            profileId={profileId}
            referenceKeys={[referenceKey]}
            providers={[reference.provider]}
          />
        </div>
        <div className="min-h-0 flex-1 space-y-7 overflow-y-auto px-7 py-6">
          {reference.media.map((media) => (
            <ReferenceImage
              key={media.hash}
              profileId={profileId}
              referenceId={reference.id}
              hash={media.hash}
              title={title}
              isDetail
            />
          ))}
          {reference.text ? (
            <p className="text-foreground-secondary text-sm leading-7 break-words whitespace-pre-wrap">
              {reference.text}
            </p>
          ) : null}
          {reference.note ? (
            <section>
              <h3 className="text-muted-foreground mb-2 text-xs font-medium">
                Your note
              </h3>
              <p className="text-foreground-secondary text-sm leading-7 break-words whitespace-pre-wrap">
                {reference.note}
              </p>
            </section>
          ) : null}
          <section>
            <h3 className="text-muted-foreground mb-2 text-xs font-medium">
              {reference.unsupportedReason
                ? 'Analysis unavailable'
                : EVIDENCE_HEADINGS[
                    reference.observation?.evidence ?? 'observation'
                  ]}
            </h3>
            <p className="text-foreground-secondary text-sm leading-7 break-words whitespace-pre-wrap">
              {reference.unsupportedReason ??
                reference.observation?.description ??
                'No analysis saved yet.'}
            </p>
          </section>
          <section>
            <h3 className="text-muted-foreground mb-3 text-xs font-medium">
              Saved in
            </h3>
            <ul className="space-y-2">
              {sources
                .filter((source) => reference.sourceIds.includes(source.id))
                .map((source) => (
                  <li
                    key={source.id}
                    className="bg-fill-subtle flex flex-wrap items-center justify-between gap-2 rounded-md px-3 py-2.5 text-xs"
                  >
                    <span>{source.title}</span>
                    {!source.isIncluded ? (
                      <span className="text-muted-foreground">
                        Excluded from generation
                      </span>
                    ) : null}
                  </li>
                ))}
            </ul>
          </section>
          {originalUrl ? (
            <a
              href={originalUrl}
              target="_blank"
              rel="noopener noreferrer"
              onClick={() =>
                posthog?.capture('library_reference_original_opened', {
                  provider: reference.provider,
                })
              }
              className="hover:text-foreground focus-visible:text-foreground focus-visible:bg-active text-foreground-secondary -mx-1.5 -my-1 inline-flex items-center gap-1 rounded-md px-1.5 py-1 text-xs underline-offset-4 transition-colors hover:underline focus-visible:underline focus-visible:outline-hidden"
            >
              Open original
              <ArrowUpRight size={14} weight="bold" aria-hidden />
            </a>
          ) : null}
        </div>
      </DialogContent>
    </Dialog>
  );
};
