import { useSyncExternalStore } from 'react';
import AuthScreenView from '@/components/AuthScreenView';
import { useLogin } from '@/hooks/useLogin';
import { browserSessionToken } from '@/library/browserSession';
import {
  hasLibrarySession,
  saveLibrarySession,
  subscribeLibrarySession,
  librarySessionError,
  librarySessionRevision,
} from '@/library/api';
import LibraryApp from '@/library/LibraryApp';
import { fetchLocalApi } from '@/utils/localApi';
import { ErrorResponseSchema } from '@rivet/core/types/api-responses';

interface LoginCredentials {
  token: string;
  refreshToken?: string;
  installRef?: string;
}

const completeLibraryLogin = async (
  credentials: LoginCredentials,
): Promise<void> => {
  const revision = librarySessionRevision();
  const response = await fetchLocalApi('/api/library/browser-sessions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(credentials),
  });
  if (!response.ok) {
    const body = ErrorResponseSchema.safeParse(
      await response.json().catch(() => null),
    );
    throw new Error(
      body.success ? body.data.error : 'Could not start a library session.',
    );
  }
  saveLibrarySession(browserSessionToken(await response.json()), revision);
};

const LibrarySignIn = () => {
  const storageError = useSyncExternalStore(
    subscribeLibrarySession,
    librarySessionError,
  );
  const { startLogin, isStartingLogin, loginError, signInUrl } = useLogin(
    'library',
    completeLibraryLogin,
  );
  return (
    <AuthScreenView
      isSigningIn={isStartingLogin}
      onStartSignIn={() => void startLogin()}
      errorMessage={loginError ?? storageError}
      signInUrl={signInUrl}
    />
  );
};

const LibraryEntry = () => {
  const isAuthenticated = useSyncExternalStore(
    subscribeLibrarySession,
    hasLibrarySession,
  );
  return isAuthenticated ? <LibraryApp /> : <LibrarySignIn />;
};

export default LibraryEntry;
