import { useMutation, useQueryClient } from '@tanstack/react-query';
import { usePostHog } from 'posthog-js/react';
import { Copy, WarningCircle } from '@phosphor-icons/react';
import Button from '@/components/Button';
import { requestLibrary } from '@/library/api';
import {
  ReferenceProviderLabel,
  referenceProviderName,
} from '@/library/ReferenceProviderLabel';
import { copyVariantContext } from '@/utils/copyVariantContext';
import { formatAgentPastePackage } from '@/utils/agentPastePackage';
import { ReferenceProfileStatusResponseSchema } from '@rivet/core/types/api-responses';
import type {
  DesignLibraryImport,
  DesignLibraryImportReason,
} from '@rivet/core/types/design-library';
import { errorMessage } from '@rivet/core/utils/errorMessage';
import { queryKeys } from '@/utils/queryKeys';

const MAC_PLATFORM = 'darwin';
const IMPORT_FAILED_ASK = 'Help me fix this Rivet import.';
const IMPORT_RETRY_STEP =
  'Once it’s fixed, press Retry on the References page.';

const importReasonCopy = (item: DesignLibraryImport): string => {
  const reason: DesignLibraryImportReason = item.reason ?? 'unknown';
  switch (reason) {
    case 'rate_limited':
      return `Waiting on ${referenceProviderName(item.provider)}. Rivet will try again automatically.`;
    case 'source_unavailable':
      return `We couldn’t reach ${referenceProviderName(item.provider)}.`;
    case 'images_unavailable':
      return 'Some images couldn’t be downloaded.';
    case 'agent_unavailable':
      return 'Your coding agent isn’t set up.';
    case 'agent_failed':
      return 'Your coding agent couldn’t finish. Check that it’s signed in.';
    case 'search_unsupported':
      return item.diagnostics?.platform === MAC_PLATFORM
        ? 'Search isn’t available on this Mac yet.'
        : 'Search isn’t available on this computer yet.';
    case 'search_unavailable':
      return 'Search couldn’t start.';
    case 'unknown':
      return 'Something went wrong.';
    default: {
      const unhandled: never = reason;
      return unhandled;
    }
  }
};

const failedImportTitle = (item: DesignLibraryImport): string =>
  item.analyzedCount < item.referenceCount
    ? 'We couldn’t analyze these references'
    : 'We couldn’t make these references searchable';

export const importAgentPastePackage = (item: DesignLibraryImport) =>
  formatAgentPastePackage({
    problem: `${failedImportTitle(item)} from ${referenceProviderName(item.provider)}. ${importReasonCopy(item)}`,
    reasonCode: item.diagnostics?.reasonCode ?? undefined,
    reasonDetail: item.diagnostics?.detail ?? undefined,
    ask: IMPORT_FAILED_ASK,
    nextStep: IMPORT_RETRY_STEP,
    rivetVersion: __RIVET_VERSION__,
    nodeVersion: item.diagnostics?.nodeVersion,
    platform: item.diagnostics
      ? `${item.diagnostics.platform} ${item.diagnostics.arch}`
      : undefined,
    importProvider: item.provider,
    importJobId: item.jobId,
    failedStep: item.diagnostics?.failedStep ?? undefined,
    analyzedReferences: `${item.analyzedCount} of ${item.referenceCount}`,
  });

const ImportProgress = ({ item }: { item: DesignLibraryImport }) => (
  <span className="text-muted-foreground">
    {item.analyzedCount} of {item.referenceCount} analyzed
  </span>
);

const PendingImport = ({ item }: { item: DesignLibraryImport }) => (
  <p role="status" className="text-muted-foreground flex flex-wrap gap-x-2">
    <span className="text-foreground-secondary">
      <ReferenceProviderLabel provider={item.provider} />
    </span>
    <span>Importing</span>
    <ImportProgress item={item} />
    {item.reason ? <span>{importReasonCopy(item)}</span> : null}
  </p>
);

const FailedImport = ({ item }: { item: DesignLibraryImport }) => {
  const posthog = usePostHog();
  const queryClient = useQueryClient();
  const retry = useMutation({
    mutationFn: () =>
      requestLibrary(`/profile/jobs/${encodeURIComponent(item.jobId)}`, {
        schema: ReferenceProfileStatusResponseSchema,
        method: 'PATCH',
        body: { action: 'retry' },
      }),
    onSuccess: () =>
      queryClient.invalidateQueries({ queryKey: queryKeys.designLibraryAll }),
  });
  return (
    <div role="alert" className="flex items-start gap-2">
      <WarningCircle
        aria-hidden
        className="text-muted-foreground mt-0.5 size-4 shrink-0"
      />
      <div className="min-w-0 flex-1 space-y-1">
        <p className="flex flex-wrap gap-x-2">
          <span className="text-foreground-secondary">
            <ReferenceProviderLabel provider={item.provider} />
          </span>
          <span className="text-foreground">{failedImportTitle(item)}</span>
          <ImportProgress item={item} />
        </p>
        <p className="text-muted-foreground">{importReasonCopy(item)}</p>
        {retry.isError ? (
          <p className="text-muted-foreground">
            {errorMessage(retry.error, 'Could not retry this import.')}
          </p>
        ) : null}
      </div>
      <div className="flex shrink-0 items-center gap-2">
        <Button
          variant="ghost"
          size="compact"
          leadingIcon={Copy}
          onClick={() =>
            void copyVariantContext({
              text: importAgentPastePackage(item),
              copyKind: 'import_failure_report',
            })
          }
        >
          Copy for agent
        </Button>
        <Button
          variant="secondary"
          size="compact"
          disabled={retry.isPending}
          onClick={() => {
            posthog?.capture('library_reference_import_retried', {
              provider: item.provider,
            });
            retry.mutate();
          }}
        >
          {retry.isPending ? 'Retrying…' : 'Retry'}
        </Button>
      </div>
    </div>
  );
};

export const LibraryImportStatus = ({
  imports,
}: {
  imports: DesignLibraryImport[];
}) =>
  imports.length ? (
    <div className="border-border-subtle mb-6 space-y-3 rounded-lg border p-3 text-xs">
      {imports.map((item) =>
        item.state === 'failed' ? (
          <FailedImport key={item.jobId} item={item} />
        ) : (
          <PendingImport key={item.jobId} item={item} />
        ),
      )}
    </div>
  ) : null;
