import { useCallback, useRef, useState, type ReactNode } from 'react';
import { ProjectCardActions } from '@/library/ProjectCardActions';
import {
  latestVariantDates,
  formatProjectEdit,
  sortProjects,
} from '@/library/projectSort';
import { LibraryLayout } from '@/library/LibraryLayout';
import Button from '@/components/Button';
import TextInput from '@/components/TextInput';
import { FolderOpen, MagnifyingGlass, PushPin } from '@phosphor-icons/react';
import type {
  LibraryDirection,
  LibraryProject,
  LibraryProjectPreview,
} from '@rivet/core/types/project-library';

interface ProjectLibraryViewProps {
  projects: LibraryProject[];
  variants: LibraryDirection[] | undefined;
  historyError?: string;
  onRetryHistory?: () => void;
  projectPreviews?: Record<string, LibraryProjectPreview | null | undefined>;
  selectedProjectId: string | null;
  onSelectProject: (projectId: string) => void;
  onBrowseLibrary: () => void;
  onOpenProject: (projectId?: string) => void;
  onRenameProject: (projectId: string, name: string) => Promise<void>;
  onRemoveProject: (projectId: string) => Promise<void>;
  onSetProjectPinned: (projectId: string, isPinned: boolean) => Promise<void>;
  isOpeningProject?: boolean;
  projectOpenError?: string;
  onSearchCompleted?: (queryLength: number) => void;
  accountMenu?: ReactNode;
  navigation?: ReactNode;
  view?: 'library' | 'references';
  children?: ReactNode;
}

export const ProjectLibraryView = ({
  projects,
  variants,
  historyError,
  onRetryHistory,
  projectPreviews = {},
  selectedProjectId,
  onSelectProject,
  onBrowseLibrary,
  onOpenProject,
  onRenameProject,
  onRemoveProject,
  onSetProjectPinned,
  isOpeningProject = false,
  projectOpenError,
  onSearchCompleted,
  accountMenu,
  navigation,
  view = 'library',
  children,
}: ProjectLibraryViewProps) => {
  const [search, setSearch] = useState('');
  const isGalleryVisible = selectedProjectId === null || children === undefined;
  const heading = useRef<HTMLHeadingElement>(null);
  const listScrollTop = useRef(0);
  const restoreListPosition = useCallback((list: HTMLDivElement | null) => {
    if (list) list.scrollTop = listScrollTop.current;
  }, []);
  const latestEdits = latestVariantDates(variants);
  const [now] = useState(Date.now);
  const selectedProject = projects.find(
    (project) => project.id === selectedProjectId,
  );
  const variantCounts = new Map<string, number>();
  if (variants) {
    for (const project of projects) {
      if (!project.historyIssue) variantCounts.set(project.id, 0);
    }
  }
  for (const { projectId } of variants ?? []) {
    const count = variantCounts.get(projectId);
    if (count !== undefined) variantCounts.set(projectId, count + 1);
  }
  const visibleProjects = sortProjects({
    projects: projects.filter((entry) =>
      entry.name.toLowerCase().includes(search.toLowerCase()),
    ),
    latestEdits,
  });
  return (
    <div
      className="ph-no-capture bg-background text-foreground flex h-screen min-h-0"
      data-rivet-private
    >
      <main className="relative flex min-w-0 flex-1 flex-col overflow-hidden">
        <LibraryLayout
          navigation={navigation}
          onBrowseProjects={onBrowseLibrary}
          isHeaderVisible={isGalleryVisible}
          controls={
            view === 'library' ? (
              <TextInput
                type="search"
                leadingIcon={MagnifyingGlass}
                aria-label="Search projects"
                placeholder="Search projects…"
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                onBlur={() => onSearchCompleted?.(search.length)}
                containerClassName="w-64 max-sm:flex-1"
                className="text-xs"
              />
            ) : null
          }
        >
          {projectOpenError ? (
            <p
              role="alert"
              className="text-muted-foreground px-10 pt-5 text-xs"
            >
              {projectOpenError}
            </p>
          ) : null}
          {children !== undefined ? (
            children
          ) : (
            <div
              ref={restoreListPosition}
              onScroll={(event) => {
                listScrollTop.current = event.currentTarget.scrollTop;
              }}
              className="min-h-0 flex-1 overflow-y-auto px-10 pb-10 max-sm:px-5"
            >
              <h1 ref={heading} tabIndex={-1} className="sr-only">
                Projects
              </h1>
              <div className="mb-9 flex items-center justify-end">
                <Button
                  onClick={() => onOpenProject()}
                  variant="secondary"
                  disabled={isOpeningProject}
                  leadingIcon={FolderOpen}
                  className="shrink-0"
                >
                  Open project…
                </Button>
              </div>
              {historyError ? (
                <div
                  role="alert"
                  className="mb-6 flex items-center gap-3 text-xs"
                >
                  <span className="text-muted-foreground">{historyError}</span>
                  <Button
                    onClick={onRetryHistory}
                    variant="ghost"
                    size="compact"
                    className="shrink-0"
                  >
                    Retry history
                  </Button>
                </div>
              ) : null}
              {selectedProject?.issue ? (
                <p
                  role="alert"
                  className="border-accent-warning/10 bg-accent-warning/[0.03] text-foreground-secondary mb-6 rounded-lg border p-4 text-xs leading-6"
                >
                  {selectedProject.issue}
                </p>
              ) : null}
              {selectedProject && !selectedProject.isAvailable ? (
                <div className="border-accent-warning/10 bg-accent-warning/[0.03] text-foreground-tertiary mb-6 flex items-center justify-between gap-4 rounded-lg border p-4 text-xs">
                  <span>
                    Locate {selectedProject.name}’s working folder to open its
                    workspace.
                  </span>
                  <Button
                    disabled={isOpeningProject}
                    onClick={() => onOpenProject(selectedProject.id)}
                    variant="secondary"
                    size="compact"
                    className="shrink-0"
                  >
                    Locate folder
                  </Button>
                </div>
              ) : null}
              <div className="grid items-start gap-x-6 gap-y-8 sm:grid-cols-2">
                {visibleProjects.map((entry) => {
                  const variantCount = variantCounts.get(entry.id);
                  let variantCountLabel = 'Loading variants…';
                  if (variantCount !== undefined)
                    variantCountLabel = `${variantCount.toLocaleString()} ${variantCount === 1 ? 'variant' : 'variants'}`;
                  else if (historyError || entry.historyIssue)
                    variantCountLabel = 'Variants unavailable';
                  const editedAt = latestEdits.get(entry.id);
                  let editLabel = 'No edits yet';
                  if (historyError || entry.historyIssue)
                    editLabel = 'Edit history unavailable';
                  else if (variants === undefined) editLabel = 'Loading edits…';
                  else if (variantCount) editLabel = 'Edit date unavailable';
                  const preview = projectPreviews[entry.id];
                  return (
                    <div key={entry.id} className="group/project grid min-w-0">
                      <button
                        onClick={() => {
                          setSearch('');
                          onSelectProject(entry.id);
                        }}
                        className="group hover:bg-hover focus-visible:bg-active col-start-1 row-span-2 row-start-1 -m-2 grid w-[calc(100%+1rem)] min-w-0 grid-rows-subgrid rounded-2xl p-2 text-left transition-colors focus-visible:outline-hidden"
                      >
                        <span className="group-hover:border-border group-focus-visible:border-muted-foreground border-border-subtle bg-fill-subtle relative block aspect-video overflow-hidden rounded-xl border">
                          {preview ? (
                            <img
                              src={preview.dataUrl}
                              alt={`${entry.name} — ${preview.label}`}
                              draggable={false}
                              className="h-full w-full object-cover object-top"
                            />
                          ) : null}
                        </span>
                        <span className="mt-3 block pr-16">
                          <span className="flex min-w-0 items-center gap-1.5 text-sm font-medium">
                            {entry.pinnedAt ? (
                              <PushPin
                                size={12}
                                weight="fill"
                                aria-hidden
                                className="text-soft-foreground shrink-0"
                              />
                            ) : null}
                            <span className="truncate">{entry.name}</span>
                          </span>
                          <span className="text-muted-foreground group-hover:text-soft-foreground group-focus-visible:text-soft-foreground mt-2 flex min-w-0 flex-wrap items-center gap-x-3 gap-y-1 text-xs">
                            {editedAt !== undefined ? (
                              <time
                                dateTime={new Date(editedAt).toISOString()}
                                title={new Date(editedAt).toLocaleString()}
                              >
                                {formatProjectEdit({ editedAt, now })}
                              </time>
                            ) : (
                              <span>{editLabel}</span>
                            )}
                            <span className="shrink-0">
                              {variantCountLabel}
                            </span>
                          </span>
                          {!entry.isAvailable ? (
                            <span className="text-accent-warning mt-2 block text-xs">
                              Folder unavailable
                            </span>
                          ) : null}
                        </span>
                      </button>
                      <div className="z-content col-start-1 row-start-2 mt-3 self-center justify-self-end">
                        <ProjectCardActions
                          project={entry}
                          onRename={onRenameProject}
                          onSetPinned={onSetProjectPinned}
                          onRemove={async (projectId) => {
                            await onRemoveProject(projectId);
                            heading.current?.focus();
                          }}
                        />
                      </div>
                    </div>
                  );
                })}
                {visibleProjects.length === 0 ? (
                  <div className="border-border col-span-full flex min-h-80 flex-col items-center justify-center rounded-xl border border-dashed px-8 text-center">
                    <FolderOpen
                      size={26}
                      weight="bold"
                      className="text-foreground-faint mb-5"
                      aria-hidden
                    />
                    <h2 className="text-sm font-medium">
                      {search ? 'No matching projects' : 'Add your projects'}
                    </h2>
                    <p className="text-muted-foreground mt-2 max-w-sm text-xs leading-6">
                      {search
                        ? 'Try another project name.'
                        : 'Open an existing project to add it as a project here'}
                    </p>
                    {!search ? (
                      <Button
                        onClick={() => onOpenProject()}
                        variant="secondary"
                        disabled={isOpeningProject}
                        className="mt-5"
                      >
                        Open project
                      </Button>
                    ) : null}
                  </div>
                ) : null}
              </div>
            </div>
          )}
          {isGalleryVisible && accountMenu ? (
            <footer className="border-separator bg-card shrink-0 border-t px-2.5 py-2.5">
              {accountMenu}
            </footer>
          ) : null}
        </LibraryLayout>
      </main>
    </div>
  );
};
