import { useMutation, useQueryClient } from '@tanstack/react-query';
import type {
  LibraryProject,
  ProjectLibrarySnapshot,
} from '@rivet/core/types/project-library';
import {
  LibraryProjectRemovalResponseSchema,
  LibraryProjectResponseSchema,
} from '@rivet/core/types/api-responses';
import { requestLibrary } from '@/library/api';
import { queryKeys } from '@/utils/queryKeys';

export const useProjectManagement = () => {
  const client = useQueryClient();
  const updateProjects = async (
    update: (projects: LibraryProject[]) => LibraryProject[],
  ) => {
    await client.cancelQueries({ queryKey: queryKeys.projectLibrary.all });
    client.setQueryData<{ projects: LibraryProject[] }>(
      queryKeys.projectLibrary.projects,
      (data) => (data ? { projects: update(data.projects) } : data),
    );
    client.setQueriesData<ProjectLibrarySnapshot>(
      { queryKey: queryKeys.projectLibrary.histories },
      (data) => {
        if (!data) return data;
        const projects = update(data.projects);
        const ids = new Set(projects.map(({ id }) => id));
        return {
          projects,
          variants: data.variants.filter(({ projectId }) => ids.has(projectId)),
        };
      },
    );
    void client.invalidateQueries({ queryKey: queryKeys.projectLibrary.all });
  };
  const rename = useMutation({
    mutationFn: ({ projectId, name }: { projectId: string; name: string }) =>
      requestLibrary(`/projects/${encodeURIComponent(projectId)}`, {
        schema: LibraryProjectResponseSchema,
        method: 'PATCH',
        body: { name },
      }),
    onSuccess: ({ project }) =>
      updateProjects((projects) =>
        projects.map((entry) =>
          entry.id === project.id ? { ...entry, name: project.name } : entry,
        ),
      ),
  });
  const pin = useMutation({
    mutationFn: ({
      projectId,
      isPinned,
    }: {
      projectId: string;
      isPinned: boolean;
    }) =>
      requestLibrary(`/projects/${encodeURIComponent(projectId)}/pin`, {
        schema: LibraryProjectResponseSchema,
        method: isPinned ? 'PUT' : 'DELETE',
      }),
    onSuccess: ({ project }) =>
      updateProjects((projects) =>
        projects.map((entry) =>
          entry.id === project.id
            ? { ...entry, pinnedAt: project.pinnedAt }
            : entry,
        ),
      ),
  });
  const remove = useMutation({
    mutationFn: (projectId: string) =>
      requestLibrary(`/projects/${encodeURIComponent(projectId)}`, {
        schema: LibraryProjectRemovalResponseSchema,
        method: 'DELETE',
      }),
    onSuccess: async (_result, projectId) => {
      await updateProjects((projects) =>
        projects.filter(({ id }) => id !== projectId),
      );
      await client.cancelQueries({
        queryKey: queryKeys.libraryProjectPreview.project(projectId),
      });
      client.removeQueries({
        queryKey: queryKeys.libraryProjectPreview.project(projectId),
      });
    },
  });
  return {
    setProjectPinned: async (
      projectId: string,
      isPinned: boolean,
    ): Promise<void> => {
      await pin.mutateAsync({ projectId, isPinned });
    },
    renameProject: async (projectId: string, name: string): Promise<void> => {
      await rename.mutateAsync({ projectId, name });
    },
    removeProject: async (projectId: string): Promise<void> => {
      await remove.mutateAsync(projectId);
    },
  };
};
