import { useCallback, useRef, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { ImageBroken } from '@phosphor-icons/react';
import clsx from 'clsx';
import { readReferenceMedia } from '@/library/referenceMedia';
import { queryKeys } from '@/utils/queryKeys';

interface ReferenceImageProps {
  profileId: string;
  referenceId: string;
  hash: string;
  title: string;
  isDetail?: boolean;
}

const IMAGE_MARGIN = '200px';

export const ReferenceImage = ({
  profileId,
  referenceId,
  hash,
  title,
  isDetail = false,
}: ReferenceImageProps) => {
  const [isVisible, setIsVisible] = useState(false);
  const [isInvalid, setIsInvalid] = useState(false);
  const observer = useRef<IntersectionObserver | null>(null);
  const attach = useCallback((element: HTMLDivElement | null) => {
    observer.current?.disconnect();
    if (!element) return;
    observer.current = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setIsVisible(true);
          observer.current?.disconnect();
        }
      },
      { rootMargin: IMAGE_MARGIN },
    );
    observer.current.observe(element);
  }, []);
  const image = useQuery({
    queryKey: queryKeys.designLibraryImage({ profileId, referenceId, hash }),
    queryFn: async ({ signal }) => {
      const blob = await readReferenceMedia({
        profileId,
        referenceId,
        hash,
        signal,
      });
      return new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () =>
          typeof reader.result === 'string'
            ? resolve(reader.result)
            : reject(new Error('Image unavailable'));
        reader.onerror = () => reject(new Error('Image unavailable'));
        reader.readAsDataURL(blob);
      });
    },
    enabled: isVisible,
    staleTime: Infinity,
    gcTime: 0,
    retry: false,
  });
  const hasImage = Boolean(image.data) && !isInvalid;
  return (
    <div
      ref={attach}
      className={clsx(
        'bg-fill-subtle flex items-center justify-center overflow-hidden',
        isDetail ? 'min-h-32' : null,
        !isDetail && !hasImage ? 'aspect-[4/3]' : null,
      )}
    >
      {image.isError || isInvalid ? (
        <span className="text-muted-foreground flex items-center gap-2 p-5 text-xs">
          <ImageBroken size={16} weight="bold" aria-hidden />
          Image unavailable
        </span>
      ) : null}
      {image.data && !isInvalid ? (
        <img
          src={image.data}
          alt={title}
          onError={() => setIsInvalid(true)}
          className={
            isDetail
              ? 'max-h-[65vh] w-full object-contain'
              : 'block h-auto w-full'
          }
        />
      ) : null}
      {!image.data && !image.isError ? (
        <span className="text-muted-foreground text-xs">Loading image…</span>
      ) : null}
    </div>
  );
};
