import { useCallback, useRef, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { usePostHog } from 'posthog-js/react';
import { Images, MagnifyingGlass } from '@phosphor-icons/react';
import Button from '@/components/Button';
import TextInput from '@/components/TextInput';
import { LibraryHeaderControls } from '@/library/LibraryLayout';
import { requestLibrary } from '@/library/api';
import { MasonryGrid, MasonryItem } from '@/components/MasonryGrid';
import { ReferenceCard } from '@/library/ReferenceCard';
import { CopyReferenceButton } from '@/library/CopyReferenceButton';
import { LibrarySourceFilter } from '@/library/LibrarySourceFilter';
import { LibraryImportStatus } from '@/library/LibraryImportStatus';
import type { ReferenceStep } from '@/library/referenceStep';
import {
  DESIGN_REFERENCE_BATCH_LIMIT,
  designLibrarySourceFilters,
  designReferenceKeys,
  DesignReferenceSearchResultSchema,
  type DesignLibrarySnapshot,
} from '@rivet/core/types/design-library';
import { queryKeys } from '@/utils/queryKeys';

interface DesignLibraryViewProps {
  snapshot: DesignLibrarySnapshot;
  onAddSources: () => void;
  isAddSourcesDisabled: boolean;
  initialOpenReferenceId?: string;
}

const PAGE_SIZE = 24;
const SCROLL_MARGIN = '200px';
const SEARCH_DELAY_MS = 350;
const SEARCH_LIMIT = 100;

export const DesignLibraryView = ({
  snapshot,
  onAddSources,
  isAddSourcesDisabled,
  initialOpenReferenceId,
}: DesignLibraryViewProps) => {
  const posthog = usePostHog();
  const [search, setSearch] = useState('');
  const [settledSearch, setSettledSearch] = useState('');
  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [sourceFilterId, setSourceFilterId] = useState<string | null>(null);
  const imageReferences = snapshot.references.filter(
    (reference) => reference.media.length > 0,
  );
  const [visibleCount, setVisibleCount] = useState(() =>
    Math.max(
      PAGE_SIZE,
      imageReferences.findIndex(({ id }) => id === initialOpenReferenceId) + 1,
    ),
  );
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [openReferenceId, setOpenReferenceId] = useState<string | null>(
    initialOpenReferenceId ?? null,
  );
  const observer = useRef<IntersectionObserver | null>(null);
  const keys = designReferenceKeys(snapshot.references);
  const sourceFilters = designLibrarySourceFilters(snapshot.sources);
  const sourceFilter = sourceFilters.find(
    (filter) => filter.id === sourceFilterId,
  );
  const semanticSearch = useQuery({
    queryKey: queryKeys.designReferenceSearch({
      profileId: snapshot.profileId,
      revision: snapshot.revision,
      references: snapshot.references.map(({ id, revision, sourceIds }) => [
        id,
        revision,
        sourceIds,
      ]),
      search: settledSearch,
      sourceId: sourceFilter?.id ?? '',
    }),
    queryFn: ({ signal }) =>
      requestLibrary('/profile/search', {
        schema: DesignReferenceSearchResultSchema,
        method: 'POST',
        body: {
          query: settledSearch,
          sourceId: sourceFilter?.id,
          limit: SEARCH_LIMIT,
        },
        signal,
      }),
    enabled: settledSearch.length >= 2 && snapshot.references.length > 0,
    retry: false,
  });
  const selectedReferences = snapshot.references.filter((reference) =>
    selectedIds.includes(reference.id),
  );
  const selectedKeys = selectedReferences.flatMap((reference) => {
    const key = keys.get(reference.id);
    return key ? [key] : [];
  });
  const query = search.trim();
  const isSearching = query.length >= 2;
  const isSearchPending =
    isSearching &&
    snapshot.references.length > 0 &&
    (settledSearch !== query || semanticSearch.isLoading);
  const hasSearchError =
    isSearching && !isSearchPending && semanticSearch.isError;
  const referenceById = new Map(
    snapshot.references.map((reference) => [reference.id, reference]),
  );
  const references = isSearching
    ? (semanticSearch.data?.results ?? []).flatMap(({ id }) => {
        const reference = referenceById.get(id);
        return reference ? [reference] : [];
      })
    : imageReferences.filter(
        (reference) =>
          !sourceFilter ||
          reference.sourceIds.some((id) => sourceFilter.sourceIds.includes(id)),
      );
  const hasReferences = imageReferences.length > 0;
  const referenceCount = references.length;
  const isOpenReferenceGone =
    openReferenceId !== null &&
    (isSearchPending || hasSearchError || !referenceById.has(openReferenceId));
  if (isOpenReferenceGone) setOpenReferenceId(null);
  const emptyTitle =
    snapshot.references.length > 0
      ? 'No images yet'
      : 'Your library starts here';
  const emptyDescription =
    snapshot.references.length > 0
      ? 'Ask your agent to save a design reference with an image to your library. It will appear here, ready to browse.'
      : 'Connect a source, then choose what to import into your library.';
  const attachSentinel = useCallback(
    (element: HTMLDivElement | null) => {
      observer.current?.disconnect();
      if (!element) return;
      observer.current = new IntersectionObserver(
        (entries) => {
          if (!entries.some((entry) => entry.isIntersecting)) return;
          observer.current?.disconnect();
          setVisibleCount(Math.min(visibleCount + PAGE_SIZE, referenceCount));
        },
        { root: element.parentElement, rootMargin: SCROLL_MARGIN },
      );
      observer.current.observe(element);
    },
    [visibleCount, referenceCount],
  );
  const stepOpenReference = (step: ReferenceStep) => {
    const openIndex = references.findIndex(
      (reference) => reference.id === openReferenceId,
    );
    const nextIndex = openIndex + step;
    const nextReference = references[nextIndex];
    if (openIndex < 0 || !nextReference) return;
    setOpenReferenceId(nextReference.id);
    setVisibleCount(Math.max(visibleCount, nextIndex + 1));
  };
  const selectReference = (referenceId: string) => {
    const current = selectedReferences.map((reference) => reference.id);
    const next = current.includes(referenceId)
      ? current.filter((id) => id !== referenceId)
      : [...current, referenceId];
    setSelectedIds(next);
    posthog?.capture('library_reference_selection_changed', {
      selected_count: next.length,
    });
  };
  return (
    <div
      className="ph-no-capture flex min-h-0 flex-1 flex-col"
      data-rivet-private
    >
      <LibraryHeaderControls>
        <TextInput
          type="search"
          leadingIcon={MagnifyingGlass}
          aria-label="Search references"
          placeholder="Search references…"
          value={search}
          containerClassName="w-64 max-sm:flex-1"
          className="text-xs"
          onChange={(event) => {
            const value = event.target.value;
            setSearch(value);
            if (searchTimer.current) clearTimeout(searchTimer.current);
            searchTimer.current = setTimeout(
              () => setSettledSearch(value.trim()),
              SEARCH_DELAY_MS,
            );
            setVisibleCount(PAGE_SIZE);
          }}
          onBlur={() => {
            const results = semanticSearch.data?.results ?? [];
            posthog?.capture('library_reference_search_completed', {
              query_length: search.length,
              result_count: isSearching ? results.length : references.length,
              ...(isSearching
                ? {
                    semantic_result_count: results.filter(
                      (result) => result.matchedBy === 'semantic',
                    ).length,
                    saved_text_result_count: results.filter(
                      (result) => result.matchedBy === 'saved_text',
                    ).length,
                    unanalyzed_result_count: results.filter(
                      (result) => !result.hasAnalysis,
                    ).length,
                  }
                : {}),
            });
          }}
        />
      </LibraryHeaderControls>
      <div className="min-h-0 flex-1 overflow-y-auto px-10 pb-10 max-sm:px-5">
        <LibraryImportStatus imports={snapshot.imports} />
        {!snapshot.isEnabled && hasReferences ? (
          <p className="text-muted-foreground mb-5 text-xs">
            Automatic use is paused. Your saved references are still here.
          </p>
        ) : null}
        {hasReferences ? (
          <div className="mb-7 flex flex-wrap items-center gap-3">
            <LibrarySourceFilter
              filters={sourceFilters}
              selected={sourceFilter}
              onSelect={(filter) => {
                setSourceFilterId(filter?.id ?? null);
                setVisibleCount(PAGE_SIZE);
                posthog?.capture('library_reference_source_filtered', {
                  is_filtered: Boolean(filter),
                  ...(filter ? { provider: filter.provider } : {}),
                });
              }}
            />
          </div>
        ) : null}
        {selectedKeys.length ? (
          <div className="bg-background border-border shadow-floating sticky top-0 z-20 mb-6 flex flex-wrap items-center gap-3 rounded-lg border p-3">
            <span className="text-foreground-tertiary text-xs">
              {selectedKeys.length} selected
            </span>
            <CopyReferenceButton
              key={selectedKeys.join(' ')}
              profileId={snapshot.profileId}
              referenceKeys={selectedKeys}
              providers={selectedReferences.map(
                (reference) => reference.provider,
              )}
            />
            <Button
              variant="ghost"
              size="compact"
              onClick={() => {
                setSelectedIds([]);
                posthog?.capture('library_reference_selection_changed', {
                  selected_count: 0,
                });
              }}
            >
              Clear selection
            </Button>
          </div>
        ) : null}
        {isSearching &&
        semanticSearch.data &&
        semanticSearch.data.coverage.analyzed <
          semanticSearch.data.coverage.saved ? (
          <p role="status" className="text-muted-foreground mb-5 text-xs">
            {semanticSearch.data.coverage.analyzed} of{' '}
            {semanticSearch.data.coverage.saved} references analyzed. The rest
            match by title and caption until analysis finishes.
          </p>
        ) : null}
        {isSearchPending ? (
          <p
            role="status"
            className="text-muted-foreground py-10 text-center text-xs"
          >
            Searching references…
          </p>
        ) : null}
        {hasSearchError ? (
          <div
            role="alert"
            className="text-foreground py-10 text-center text-xs"
          >
            <p>Search is unavailable: {semanticSearch.error.message}</p>
            <Button
              variant="ghost"
              onClick={() => {
                posthog?.capture('library_reference_search_retry');
                void semanticSearch.refetch();
              }}
            >
              Try again
            </Button>
          </div>
        ) : null}
        {!isSearchPending && !hasSearchError && references.length ? (
          <MasonryGrid>
            {references.slice(0, visibleCount).map((reference) => {
              const referenceKey = keys.get(reference.id);
              if (!referenceKey) return null;
              return (
                <MasonryItem key={reference.id}>
                  <ReferenceCard
                    profileId={snapshot.profileId}
                    reference={reference}
                    sources={snapshot.sources}
                    referenceKey={referenceKey}
                    isSelected={selectedIds.includes(reference.id)}
                    isSelectionDisabled={
                      !selectedIds.includes(reference.id) &&
                      selectedKeys.length >= DESIGN_REFERENCE_BATCH_LIMIT
                    }
                    onSelect={() => selectReference(reference.id)}
                    isOpen={openReferenceId === reference.id}
                    onOpenChange={(isOpen) =>
                      setOpenReferenceId(isOpen ? reference.id : null)
                    }
                    onStep={stepOpenReference}
                  />
                </MasonryItem>
              );
            })}
          </MasonryGrid>
        ) : null}
        {!isSearchPending && !hasSearchError && !references.length ? (
          <div className="border-border-subtle flex min-h-72 flex-col items-center justify-center rounded-xl border border-dashed px-6 text-center">
            <Images
              size={28}
              weight="light"
              className="text-foreground-faint mb-5"
              aria-hidden
            />
            <h2 className="text-foreground-secondary text-sm">
              {hasReferences || isSearching
                ? 'No references found'
                : emptyTitle}
            </h2>
            <p className="text-muted-foreground mt-2 max-w-sm text-xs leading-6">
              {hasReferences || isSearching
                ? 'Try another search or choose a different source.'
                : emptyDescription}
            </p>
            {snapshot.references.length === 0 && !isSearching ? (
              <Button
                variant="tertiary"
                className="mt-5"
                onClick={onAddSources}
                disabled={isAddSourcesDisabled}
              >
                Add sources
              </Button>
            ) : null}
          </div>
        ) : null}
        {!isSearchPending &&
        !hasSearchError &&
        references.length > visibleCount ? (
          <div
            ref={attachSentinel}
            role="status"
            className="text-muted-foreground py-8 text-center text-xs"
          >
            Loading more references…
          </div>
        ) : null}
      </div>
    </div>
  );
};
