import { useCallback, useRef, useState, type ReactNode } from 'react';

interface MasonryProps {
  children: ReactNode;
}

const ROW_HEIGHT = 8;
const MIN_ROW_SPAN = 1;

export const MasonryGrid = ({ children }: MasonryProps) => (
  <ul
    className="grid grid-cols-1 items-start gap-x-5 min-[400px]:grid-cols-2 md:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5"
    style={{ gridAutoRows: `${ROW_HEIGHT}px` }}
  >
    {children}
  </ul>
);

export const MasonryItem = ({ children }: MasonryProps) => {
  const [rowSpan, setRowSpan] = useState(MIN_ROW_SPAN);
  const observer = useRef<ResizeObserver | null>(null);
  const attach = useCallback((element: HTMLDivElement | null) => {
    observer.current?.disconnect();
    if (!element) return;
    const measure = () =>
      setRowSpan(
        Math.max(
          MIN_ROW_SPAN,
          Math.ceil(element.getBoundingClientRect().height / ROW_HEIGHT),
        ),
      );
    measure();
    observer.current = new ResizeObserver(measure);
    observer.current.observe(element);
  }, []);
  return (
    <li className="min-w-0" style={{ gridRowEnd: `span ${rowSpan}` }}>
      <div ref={attach} className="relative pb-8">
        {children}
      </div>
    </li>
  );
};
