import type { ProfileProvider } from '@rivet/core/types/design-profile';
import ReferenceProviderIcon from '@/components/ReferenceProviderIcon';

const LABELS: Record<ProfileProvider, string> = {
  arena: 'Are.na',
  cosmos: 'Cosmos',
  pinterest: 'Pinterest',
  x: 'X',
  image: 'Uploaded image',
  text: 'Saved text',
  variant: 'Saved direction',
  pdf: 'PDF',
};

export const referenceProviderName = (provider: ProfileProvider): string =>
  LABELS[provider];

export const ReferenceProviderLabel = ({
  provider,
}: {
  provider: ProfileProvider;
}) => (
  <span className="inline-flex items-center gap-1.5">
    {provider === 'arena' ||
    provider === 'cosmos' ||
    provider === 'pinterest' ||
    provider === 'x' ? (
      <ReferenceProviderIcon provider={provider} className="h-3.5 w-3.5" />
    ) : null}
    {LABELS[provider]}
  </span>
);
