import type {
  LibraryDirection,
  LibraryProject,
} from '@rivet/core/types/project-library';

interface SortProjectsOptions {
  projects: readonly LibraryProject[];
  latestEdits: ReadonlyMap<string, number>;
}

interface ProjectEditOptions {
  editedAt: number;
  now: number;
}

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;
const MONTH_MS = 30 * DAY_MS;
const YEAR_MS = 365 * DAY_MS;
const EDIT_UNITS = [
  ['year', YEAR_MS],
  ['month', MONTH_MS],
  ['week', WEEK_MS],
  ['day', DAY_MS],
  ['hour', HOUR_MS],
  ['minute', MINUTE_MS],
] as const;
const relativeTime = new Intl.RelativeTimeFormat('en', { numeric: 'always' });

export const latestVariantDates = (
  variants: readonly LibraryDirection[] | undefined,
): Map<string, number> => {
  const dates = new Map<string, number>();
  for (const variant of variants ?? []) {
    const date = Date.parse(variant.createdAt);
    if (!Number.isFinite(date)) continue;
    const latest = dates.get(variant.projectId);
    if (latest === undefined || date > latest)
      dates.set(variant.projectId, date);
  }
  return dates;
};

export const sortProjects = ({
  projects,
  latestEdits,
}: SortProjectsOptions): LibraryProject[] =>
  [...projects].sort((a, b) => {
    if (a.pinnedAt && !b.pinnedAt) return -1;
    if (b.pinnedAt && !a.pinnedAt) return 1;
    if (a.pinnedAt && b.pinnedAt)
      return a.pinnedAt.localeCompare(b.pinnedAt) || a.id.localeCompare(b.id);
    const aDate = latestEdits.get(a.id);
    const bDate = latestEdits.get(b.id);
    if (aDate === undefined && bDate !== undefined) return 1;
    if (bDate === undefined && aDate !== undefined) return -1;
    const byDate = (bDate ?? 0) - (aDate ?? 0);
    return byDate || a.name.localeCompare(b.name) || a.id.localeCompare(b.id);
  });

export const formatProjectEdit = ({
  editedAt,
  now,
}: ProjectEditOptions): string => {
  const elapsed = Math.max(0, now - editedAt);
  for (const [unit, duration] of EDIT_UNITS) {
    if (elapsed >= duration) {
      return `Edited ${relativeTime.format(-Math.floor(elapsed / duration), unit)}`;
    }
  }
  return 'Edited just now';
};
