import { useState, type ReactNode } from 'react';
import { CaretDown, Check, Stack } from '@phosphor-icons/react';
import { Menu, MenuContent, MenuItem, MenuTrigger } from '@/components/Menu';
import { LibrarySourceIcon } from '@/library/LibrarySourceIcon';
import type { DesignLibrarySourceFilter } from '@rivet/core/types/design-library';

interface LibrarySourceFilterProps {
  filters: DesignLibrarySourceFilter[];
  selected: DesignLibrarySourceFilter | undefined;
  onSelect: (filter: DesignLibrarySourceFilter | undefined) => void;
}

const ALL_SOURCES_TITLE = 'All sources';

const AllSourcesIcon = () => (
  <Stack
    weight="bold"
    aria-hidden
    className="text-foreground-tertiary h-3.5 w-3.5 shrink-0"
  />
);

const SourceOption = ({
  title,
  icon,
  isChecked,
  onSelect,
}: {
  title: string;
  icon: ReactNode;
  isChecked: boolean;
  onSelect: () => void;
}) => (
  <MenuItem isChecked={isChecked} onSelect={onSelect}>
    {icon}
    <span className="min-w-0 flex-1 truncate">{title}</span>
    {isChecked ? (
      <Check
        size={12}
        weight="bold"
        aria-hidden
        className="text-foreground shrink-0"
      />
    ) : null}
  </MenuItem>
);

export const LibrarySourceFilter = ({
  filters,
  selected,
  onSelect,
}: LibrarySourceFilterProps) => {
  const [isOpen, setIsOpen] = useState(false);
  return (
    <Menu isOpen={isOpen} onOpenChange={setIsOpen}>
      <MenuTrigger className="bg-background hover:border-border focus-visible:border-muted-foreground focus-visible:text-foreground border-border-subtle text-foreground-tertiary inline-flex max-w-64 min-w-44 items-center gap-2 rounded-lg border py-2.5 pr-4 pl-3 text-xs transition-colors focus-visible:outline-hidden">
        {selected ? (
          <LibrarySourceIcon provider={selected.provider} />
        ) : (
          <AllSourcesIcon />
        )}
        <span className="sr-only">Source: </span>
        <span className="min-w-0 flex-1 truncate text-left">
          {selected?.title ?? ALL_SOURCES_TITLE}
        </span>
        <CaretDown
          size={12}
          weight="bold"
          aria-hidden
          className="ml-2 shrink-0"
        />
      </MenuTrigger>
      <MenuContent
        aria-label="Source"
        align="start"
        className="max-h-80 max-w-72 min-w-(--radix-popover-trigger-width) overflow-y-auto"
      >
        <SourceOption
          title={ALL_SOURCES_TITLE}
          icon={<AllSourcesIcon />}
          isChecked={!selected}
          onSelect={() => onSelect(undefined)}
        />
        {filters.map((filter) => (
          <SourceOption
            key={filter.id}
            title={filter.title}
            icon={<LibrarySourceIcon provider={filter.provider} />}
            isChecked={filter.id === selected?.id}
            onSelect={() => onSelect(filter)}
          />
        ))}
      </MenuContent>
    </Menu>
  );
};
