import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  useMutation,
  useQueries,
  useQuery,
  useQueryClient,
} from '@tanstack/react-query';
import { usePostHog } from 'posthog-js/react';
import {
  ArrowLeft,
  ArrowUpRight,
  CircleNotch,
  WarningCircle,
} from '@phosphor-icons/react';
import {
  ProjectLibrarySnapshotSchema,
  type LibraryDirection,
  type LibraryProject,
} from '@rivet/core/types/project-library';
import {
  DirectionPreviewResponseSchema,
  DirectionUpdateResponseSchema,
  FolderSelectionResponseSchema,
  LibraryProjectListResponseSchema,
  LibraryProjectPreviewResponseSchema,
  LibraryProjectResponseSchema,
  NavigationAcknowledgementResponseSchema,
  ProjectRuntimeResponseSchema,
  ViewNavigationsResponseSchema,
} from '@rivet/core/types/api-responses';
import { requestLibrary } from '@/library/api';
import { ProjectLibraryView } from '@/library/ProjectLibraryView';
import { DesignLibrary } from '@/library/DesignLibrary';
import { LibraryNavigation } from '@/library/LibraryNavigation';
import { useProjectManagement } from '@/library/useProjectManagement';
import { SHOW_PROJECTS_MESSAGE } from '@/library/workspaceNavigation';
import { useThemePreference } from '@/hooks/useThemePreference';
import { THEME_QUERY_PARAMETER } from '@/utils/themeBootstrap';
import {
  createThemePreferenceMessage,
  followThemePreference,
  readThemePreferenceMessage,
  readThemeState,
  subscribeToThemePreference,
} from '@/utils/themePreference';
import Button from '@/components/Button';
import TextInput from '@/components/TextInput';
import ProfileAvatar from '@/components/ProfileAvatar';
import { useAtomValue } from 'jotai';
import { mcpEditorAtom } from '@/store/atoms';
import { withLaunchRuntime } from '@rivet/core/utils/launchRuntime';
import { useAccount } from '@/hooks/useAccount';
import { getProjectTitle, setDocumentTitle } from '@/utils/projectTitle';
import { useTelemetryIdentity } from '@/hooks/useTelemetryIdentity';
import { Toaster } from 'sonner';

import {
  readLibrarySelection,
  librarySelectionPath,
  type Selection,
} from '@/library/selection';
import { queryKeys } from '@/utils/queryKeys';
const LIBRARY_REFRESH_MS = 2_500;
const NAVIGATION_POLL_MS = 500;
const PROJECT_PREVIEW_REFRESH_MS = 60_000;
const EMPTY_PROJECTS: LibraryProject[] = [];
const EMPTY_DIRECTIONS: LibraryDirection[] = [];
const FAILURE_ICON_SIZE = 24;

const Failure = ({ error, retry }: { error: Error; retry: () => void }) => (
  <div className="m-auto max-w-md px-8 text-center">
    <div className="text-muted-foreground mb-3 flex justify-center">
      <WarningCircle aria-hidden size={FAILURE_ICON_SIZE} />
    </div>
    <p className="text-foreground text-sm">{error.message}</p>
    <Button onClick={retry} variant="tertiary" size="compact" className="mt-5">
      Try again
    </Button>
  </div>
);

const LibraryApp = () => {
  const callerAgent = useAtomValue(mcpEditorAtom);
  const posthog = usePostHog();
  useTelemetryIdentity(useAccount().data);
  const queryClient = useQueryClient();
  const { renameProject, removeProject, setProjectPinned } =
    useProjectManagement();
  const visibleSelection = useRef<string | undefined>(undefined);
  const [selection, setSelection] = useState<Selection>(() =>
    readLibrarySelection(new URL(window.location.href)),
  );
  const [viewId] = useState(() => crypto.randomUUID());
  const lastSequence = useRef(0);
  const workspaceFrame = useRef<HTMLIFrameElement>(null);
  const overview = useQuery({
    queryKey: queryKeys.projectLibrary.projects,
    queryFn: ({ signal }) =>
      requestLibrary('/projects', {
        schema: LibraryProjectListResponseSchema,
        signal,
      }),
    refetchInterval: LIBRARY_REFRESH_MS,
    retry: false,
  });
  const registeredProjects = overview.data?.projects ?? EMPTY_PROJECTS;
  const historyWorkspaces = registeredProjects
    .map(({ id, projectPath }) => ({ id, projectPath }))
    .sort((a, b) => a.id.localeCompare(b.id));
  const historyOverview = useQuery({
    queryKey: queryKeys.projectLibrary.history(historyWorkspaces),
    queryFn: ({ signal }) =>
      requestLibrary('', { schema: ProjectLibrarySnapshotSchema, signal }),
    placeholderData: (previous) => {
      if (!previous) return undefined;
      const paths = new Map(
        previous.projects.map(({ id, projectPath }) => [id, projectPath]),
      );
      if (
        !registeredProjects.every(
          ({ id, projectPath }) => paths.get(id) === projectPath,
        )
      )
        return undefined;
      const ids = new Set(registeredProjects.map(({ id }) => id));
      return {
        projects: previous.projects.filter(({ id }) => ids.has(id)),
        variants: previous.variants.filter(({ projectId }) =>
          ids.has(projectId),
        ),
      };
    },
    enabled: registeredProjects.length > 0,
    refetchInterval: LIBRARY_REFRESH_MS,
    retry: false,
  });
  const historyProjects = new Map(
    historyOverview.data?.projects.map((entry) => [entry.id, entry]),
  );
  const projects = registeredProjects.map((entry) => {
    const historyProject = historyProjects.get(entry.id);
    return {
      ...entry,
      issue: historyProject ? historyProject.issue : entry.issue,
      historyIssue: historyProject
        ? historyProject.historyIssue
        : entry.historyIssue,
    };
  });
  const directions = historyOverview.data?.variants ?? EMPTY_DIRECTIONS;
  const projectPreviews = useQueries({
    queries: projects.map((entry) => ({
      queryKey: queryKeys.libraryProjectPreview.thumbnail(
        entry.id,
        entry.projectPath,
      ),
      queryFn: ({ signal }: { signal: AbortSignal }) =>
        requestLibrary(`/projects/${entry.id}/thumbnail`, {
          schema: LibraryProjectPreviewResponseSchema,
          signal,
        }),
      enabled: selection.kind === 'library',
      refetchInterval: PROJECT_PREVIEW_REFRESH_MS,
      retry: false,
    })),
  });
  const project = projects.find((entry) => entry.id === selection.projectId);
  const projectTitle = getProjectTitle({
    name: project?.name,
    projectPath: project?.projectPath,
  });
  const direction = directions.find(
    (entry) =>
      entry.projectId === selection.projectId &&
      entry.sessionId === selection.sessionId &&
      entry.variantId === selection.variantId,
  );

  const navigate = useCallback((target: Selection) => {
    window.history.pushState(null, '', librarySelectionPath(target));
    setSelection(target);
  }, []);

  useEffect(() => {
    const resetTitle = setDocumentTitle(projectTitle);
    if (project) visibleSelection.current = project.id;
    else if (
      overview.isSuccess &&
      !overview.isFetching &&
      selection.projectId === visibleSelection.current &&
      selection.projectId
    ) {
      visibleSelection.current = undefined;
      navigate({ kind: 'library' });
    }
    return resetTitle;
  }, [
    project,
    projectTitle,
    selection.projectId,
    overview.isSuccess,
    overview.isFetching,
    navigate,
  ]);

  useEffect(() => {
    const onPopState = () =>
      setSelection(readLibrarySelection(new URL(window.location.href)));
    window.addEventListener('popstate', onPopState);
    return () => window.removeEventListener('popstate', onPopState);
  }, []);

  useEffect(() => {
    const controller = new AbortController();
    let timer: ReturnType<typeof setTimeout>;
    const poll = async () => {
      try {
        const response = await requestLibrary(`/views/${viewId}`, {
          schema: ViewNavigationsResponseSchema,
          method: 'PUT',
          body: {
            isFocused:
              document.visibilityState === 'visible' && document.hasFocus(),
          },
          signal: controller.signal,
        });
        for (const target of response.navigations) {
          if (controller.signal.aborted) return;
          if (target.sequence > lastSequence.current) {
            let kind: Selection['kind'] = 'library';
            if (target.projectId) kind = 'workspace';
            if (target.variantId) kind = 'preview';
            navigate({ ...target, kind });
            lastSequence.current = target.sequence;
          }
          await requestLibrary(`/views/${viewId}/acknowledgements`, {
            schema: NavigationAcknowledgementResponseSchema,
            method: 'POST',
            body: { sequence: target.sequence },
            signal: controller.signal,
          });
        }
      } catch {}
      if (!controller.signal.aborted)
        timer = setTimeout(() => {
          void poll();
        }, NAVIGATION_POLL_MS);
    };
    void poll();
    return () => {
      controller.abort();
      clearTimeout(timer);
    };
  }, [viewId, navigate]);

  const workspace = useQuery({
    queryKey: queryKeys.libraryWorkspace(selection.projectId),
    queryFn: () =>
      requestLibrary(`/projects/${selection.projectId}/runtime`, {
        schema: ProjectRuntimeResponseSchema,
        method: 'POST',
      }),
    enabled:
      selection.kind === 'workspace' &&
      Boolean(selection.projectId) &&
      project?.isAvailable === true,
    retry: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
  });
  const workspaceOrigin = workspace.data
    ? new URL(workspace.data.editorUrl).origin
    : null;
  const workspaceEditorUrl = useMemo(() => {
    if (selection.kind !== 'workspace' || !workspace.data) return null;
    const editor = new URL(
      withLaunchRuntime(workspace.data.editorUrl, callerAgent),
    );
    editor.searchParams.set('library', '1');
    editor.searchParams.set('libraryOrigin', window.location.origin);
    editor.searchParams.set(THEME_QUERY_PARAMETER, readThemeState().preference);
    if (selection.sessionId && selection.variantId) {
      editor.searchParams.set('historySession', selection.sessionId);
      editor.searchParams.set('historyVariant', selection.variantId);
    }
    return editor.toString();
  }, [
    selection.kind,
    selection.sessionId,
    selection.variantId,
    workspace.data,
    callerAgent,
  ]);
  const { resolvedTheme } = useThemePreference();
  const postThemeToWorkspace = useCallback(() => {
    if (!workspaceOrigin) return;
    workspaceFrame.current?.contentWindow?.postMessage(
      createThemePreferenceMessage(readThemeState().preference),
      workspaceOrigin,
    );
  }, [workspaceOrigin]);

  useEffect(() => {
    if (selection.kind !== 'workspace' || !workspaceOrigin) return;
    const onMessage = (event: MessageEvent<unknown>) => {
      if (
        !workspaceFrame.current ||
        event.source !== workspaceFrame.current.contentWindow ||
        event.origin !== workspaceOrigin
      )
        return;
      const preference = readThemePreferenceMessage(event.data);
      if (preference) followThemePreference(preference);
      if (event.data !== SHOW_PROJECTS_MESSAGE) return;
      posthog?.capture('library_view_changed', { view: 'projects' });
      navigate({ kind: 'library' });
    };
    window.addEventListener('message', onMessage);
    const stopThemeBroadcast = subscribeToThemePreference(postThemeToWorkspace);
    return () => {
      window.removeEventListener('message', onMessage);
      stopThemeBroadcast();
    };
  }, [
    selection.kind,
    workspaceOrigin,
    navigate,
    posthog,
    postThemeToWorkspace,
  ]);

  const preview = useQuery({
    queryKey: queryKeys.libraryPreview({
      projectId: selection.projectId,
      sessionId: selection.sessionId,
      variantId: selection.variantId,
    }),
    queryFn: () =>
      requestLibrary(
        `/projects/${selection.projectId}/variants/${selection.sessionId}/${selection.variantId}/preview`,
        { schema: DirectionPreviewResponseSchema, method: 'POST' },
      ),
    enabled:
      selection.kind === 'preview' && Boolean(direction?.hasStaticPreview),
    retry: false,
    refetchOnWindowFocus: false,
  });
  const rename = useMutation({
    mutationFn: (label: string) =>
      requestLibrary(
        `/projects/${selection.projectId}/variants/${selection.sessionId}/${selection.variantId}`,
        {
          schema: DirectionUpdateResponseSchema,
          method: 'PATCH',
          body: { label },
        },
      ),
    onSuccess: () =>
      queryClient.invalidateQueries({ queryKey: queryKeys.projectLibrary.all }),
  });

  const selectProject = (projectId: string) => {
    const selected = projects.find((entry) => entry.id === projectId);
    posthog?.capture('library_project_selected', {
      project_id: projectId,
      workspace_available: selected?.isAvailable ?? false,
    });
    navigate({
      kind: 'workspace',
      projectId,
    });
  };
  const openProject = useMutation({
    mutationFn: async (projectId?: string) => {
      const { projectPath } = await requestLibrary('/folder-selections', {
        schema: FolderSelectionResponseSchema,
        method: 'POST',
      });
      if (projectPath === null) return null;
      return requestLibrary(
        projectId ? `/projects/${projectId}/workspace` : '/projects',
        {
          schema: LibraryProjectResponseSchema,
          method: projectId ? 'PATCH' : 'POST',
          body: { projectPath },
        },
      );
    },
    onSuccess: (result) => {
      if (!result) return;
      void queryClient.invalidateQueries({
        queryKey: queryKeys.projectLibrary.all,
      });
      posthog?.capture('library_project_selected', {
        project_id: result.project.id,
        workspace_available: result.project.isAvailable,
      });
      navigate({ kind: 'workspace', projectId: result.project.id });
    },
    onSettled: (_result, _error, projectId) => {
      posthog?.capture('library_open_project_closed', {
        is_relink: Boolean(projectId),
      });
    },
  });
  const openChooser = (projectId?: string) => {
    if (openProject.isPending) return;
    posthog?.capture('library_open_project_opened', {
      is_relink: Boolean(projectId),
    });
    openProject.mutate(projectId);
  };
  const browseLibrary = () => {
    posthog?.capture('library_view_changed', { view: 'projects' });
    navigate({ kind: 'library' });
  };
  const openWorkspace = () => {
    posthog?.capture('library_view_changed', { view: 'workspace' });
    navigate({ ...selection, kind: 'workspace' });
  };
  const retryHistory = () => {
    posthog?.capture('library_history_retry');
    void historyOverview.refetch();
  };

  let content;
  if (
    (selection.kind === 'workspace' && project?.isAvailable !== false) ||
    selection.kind === 'preview'
  ) {
    let isWorkspaceReady = false;
    let body = (
      <div className="text-muted-foreground m-auto flex items-center gap-2 text-xs">
        <CircleNotch
          size={14}
          weight="bold"
          className="animate-spin"
          aria-hidden
        />
        Opening {project?.name ?? 'project'}…
      </div>
    );
    if (
      (overview.data && !project) ||
      (historyOverview.data && selection.variantId && !direction)
    )
      body = (
        <div className="text-foreground-tertiary m-auto text-sm">
          This project or direction is no longer in your library.
        </div>
      );
    else if (
      selection.kind === 'preview' &&
      historyOverview.error &&
      !historyOverview.data
    )
      body = <Failure error={historyOverview.error} retry={retryHistory} />;
    else if (selection.kind === 'workspace' && workspace.error)
      body = (
        <Failure
          error={workspace.error}
          retry={() => {
            void workspace.refetch();
          }}
        />
      );
    else if (workspaceEditorUrl) {
      isWorkspaceReady = true;
      body = (
        <iframe
          ref={workspaceFrame}
          key={workspaceEditorUrl}
          title={`${project?.name ?? 'Project'} workspace`}
          src={workspaceEditorUrl}
          onLoad={postThemeToWorkspace}
          allow="clipboard-write"
          data-rivet-private
          className="ph-no-capture min-h-0 w-full flex-1 border-0"
        />
      );
    } else if (selection.kind === 'preview' && preview.error)
      body = (
        <Failure
          error={preview.error}
          retry={() => {
            void preview.refetch();
          }}
        />
      );
    else if (selection.kind === 'preview' && preview.data)
      body = (
        <iframe
          title={`${direction?.label ?? 'Saved direction'} preview`}
          src={preview.data.url}
          sandbox="allow-scripts allow-same-origin allow-forms allow-popups"
          className="bg-canvas min-h-0 w-full flex-1 border-0"
        />
      );
    else if (
      selection.kind === 'preview' &&
      direction &&
      !direction.hasStaticPreview
    )
      body = (
        <div className="m-auto max-w-sm text-center">
          <p className="text-sm">
            {direction.hasInteractivePreview
              ? 'Open this direction in its workspace'
              : 'This direction contains saved code changes'}
          </p>
          <p className="text-muted-foreground mt-2 text-xs leading-6">
            {direction.hasInteractivePreview
              ? 'Rivet will start the preview with this project’s dependencies and configuration.'
              : 'Open the project to continue working with its saved history.'}
          </p>
          <Button
            onClick={openWorkspace}
            disabled={project?.isAvailable === false}
            variant="primary"
            className="mt-5"
          >
            Open workspace
          </Button>
        </div>
      );
    content = (
      <>
        {selection.kind === 'preview' ? (
          <header className="border-border-subtle flex h-14 shrink-0 items-center gap-3 border-b px-5">
            <Button
              aria-label="Back to projects"
              onClick={browseLibrary}
              variant="ghost"
              size="icon-compact"
            >
              <ArrowLeft size={15} weight="bold" aria-hidden />
            </Button>
            <span className="text-muted-foreground text-xs">
              {project?.name}
            </span>
            {direction ? (
              <>
                <span aria-hidden className="text-foreground-faint">
                  /
                </span>
                <form
                  key={`${direction.projectId}:${direction.variantId}`}
                  onSubmit={(event) => {
                    event.preventDefault();
                    const data = new FormData(event.currentTarget);
                    rename.mutate(String(data.get('label')));
                  }}
                  className="flex min-w-0 flex-1 gap-2"
                >
                  <TextInput
                    name="label"
                    aria-label="Direction name"
                    defaultValue={direction.label}
                    size="compact"
                    className="-ml-2.5 max-w-xs flex-1 border-transparent bg-transparent"
                  />
                  <Button
                    type="submit"
                    disabled={rename.isPending}
                    variant="ghost"
                    size="compact"
                  >
                    Rename
                  </Button>
                </form>
              </>
            ) : (
              <span className="flex-1" />
            )}
            {selection.kind === 'preview' ? (
              <Button
                onClick={openWorkspace}
                disabled={project?.isAvailable === false}
                variant="tertiary"
                size="compact"
                trailingIcon={ArrowUpRight}
              >
                Edit in project
              </Button>
            ) : null}
          </header>
        ) : null}
        {selection.kind === 'workspace' && !isWorkspaceReady ? (
          <Button
            onClick={browseLibrary}
            variant="ghost"
            size="compact"
            className="absolute top-5 left-5"
          >
            Projects
          </Button>
        ) : null}
        {rename.error ? (
          <p role="alert" className="text-muted-foreground px-5 py-2 text-xs">
            {rename.error.message}
          </p>
        ) : null}
        {body}
      </>
    );
  }
  let viewContent = content;
  if (overview.error && !overview.data)
    viewContent = (
      <Failure
        error={overview.error}
        retry={() => {
          void overview.refetch();
        }}
      />
    );
  else if (overview.isPending)
    viewContent = (
      <div
        role="status"
        className="text-muted-foreground flex min-h-0 flex-1 items-center justify-center text-xs"
      >
        Loading projects…
      </div>
    );
  const galleryView =
    selection.kind === 'references' ? 'references' : 'library';
  const navigation = (
    <LibraryNavigation
      view={galleryView}
      onNavigate={(kind) => {
        posthog?.capture('library_view_changed', {
          view: kind === 'references' ? 'references' : 'projects',
        });
        navigate({ kind });
      }}
    />
  );
  if (selection.kind === 'references')
    viewContent = (
      <DesignLibrary
        onBrowseProjects={browseLibrary}
        initialOpenReferenceId={selection.referenceId}
      />
    );
  return (
    <>
      <ProjectLibraryView
        projects={projects}
        variants={historyOverview.data?.variants}
        historyError={historyOverview.error?.message}
        onRetryHistory={retryHistory}
        projectPreviews={Object.fromEntries(
          projects.map((entry, index) => [
            entry.id,
            projectPreviews[index]?.data?.preview,
          ]),
        )}
        selectedProjectId={selection.projectId ?? null}
        onSelectProject={selectProject}
        onBrowseLibrary={browseLibrary}
        navigation={navigation}
        view={galleryView}
        onOpenProject={openChooser}
        onRenameProject={renameProject}
        onRemoveProject={removeProject}
        onSetProjectPinned={setProjectPinned}
        accountMenu={<ProfileAvatar side="top" align="start" />}
        isOpeningProject={openProject.isPending}
        projectOpenError={openProject.error?.message}
        onSearchCompleted={(queryLength) =>
          posthog?.capture('library_search_completed', {
            query_length: queryLength,
          })
        }
      >
        {viewContent}
      </ProjectLibraryView>
      <Toaster position="bottom-right" theme={resolvedTheme} />
    </>
  );
};

export default LibraryApp;
