import {
  FilePdf,
  GitBranch,
  TextT,
  UploadSimple,
  type Icon,
} from '@phosphor-icons/react';
import ReferenceProviderIcon from '@/components/ReferenceProviderIcon';
import {
  isRemoteProfileProvider,
  type ProfileProvider,
} from '@rivet/core/types/design-profile';
import { cn } from '@/lib/utils';

type LocalProfileProvider = 'image' | 'text' | 'pdf' | 'variant';

const LOCAL_PROVIDER_ICONS: Record<LocalProfileProvider, Icon> = {
  image: UploadSimple,
  text: TextT,
  pdf: FilePdf,
  variant: GitBranch,
};

const ICON_SIZE_CLASS = 'h-3.5 w-3.5 shrink-0';

export const LibrarySourceIcon = ({
  provider,
}: {
  provider: ProfileProvider;
}) => {
  if (isRemoteProfileProvider(provider))
    return (
      <ReferenceProviderIcon provider={provider} className={ICON_SIZE_CLASS} />
    );
  const LocalIcon = LOCAL_PROVIDER_ICONS[provider];
  return (
    <LocalIcon
      weight="bold"
      aria-hidden
      className={cn(ICON_SIZE_CLASS, 'text-foreground-tertiary')}
    />
  );
};
