import { useState } from 'react';
import { Check, Copy } from '@phosphor-icons/react';
import { usePostHog } from 'posthog-js/react';
import { toast } from 'sonner';
import Button from '@/components/Button';

interface CopyButtonProps {
  label: string;
  onCopy: () => Promise<void>;
  referenceCount?: number;
  provider?: string;
}

export const CopyButton = ({
  label,
  onCopy,
  referenceCount = 1,
  provider,
}: CopyButtonProps) => {
  const posthog = usePostHog();
  const [status, setStatus] = useState<
    'idle' | 'copying' | 'copied' | 'failed'
  >('idle');
  const copy = async () => {
    setStatus('copying');
    try {
      await onCopy();
      setStatus('copied');
      posthog?.capture('library_reference_copy_completed', {
        reference_count: referenceCount,
        copy_kind: 'agent',
        ...(provider ? { provider } : {}),
      });
    } catch {
      setStatus('failed');
      toast.error('Could not copy. Check clipboard access and try again.');
      posthog?.capture('library_reference_copy_failed', {
        reference_count: referenceCount,
        copy_kind: 'agent',
        ...(provider ? { provider } : {}),
      });
    }
  };
  const ActionIcon = status === 'copied' ? Check : Copy;
  const actionLabel = status === 'copied' ? 'Copied' : label;
  return (
    <>
      <Button
        variant="secondary"
        size="compact"
        leadingIcon={ActionIcon}
        disabled={status === 'copying'}
        onClick={() => void copy()}
        aria-label={actionLabel}
        aria-live="polite"
      >
        <span className="grid whitespace-nowrap">
          <span aria-hidden className="invisible col-start-1 row-start-1">
            {label}
          </span>
          <span className="col-start-1 row-start-1">{actionLabel}</span>
        </span>
      </Button>
      {status === 'failed' ? (
        <span role="alert" className="sr-only">
          Could not copy. Check clipboard access and try again.
        </span>
      ) : null}
    </>
  );
};
