import { cn } from '@/lib/utils';

interface LibraryNavigationProps {
  view: 'library' | 'references';
  onNavigate: (view: 'library' | 'references') => void;
}

export const LibraryNavigation = ({
  view,
  onNavigate,
}: LibraryNavigationProps) => (
  <nav
    aria-label="Library"
    className="bg-surface-2 flex items-center gap-1 rounded-lg p-1"
  >
    {(['library', 'references'] as const).map((target) => (
      <a
        key={target}
        href={
          target === 'library' ? '/rivet/library' : '/rivet/library/references'
        }
        aria-current={view === target ? 'page' : undefined}
        onClick={(event) => {
          if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey)
            return;
          event.preventDefault();
          onNavigate(target);
        }}
        className={cn(
          'rounded-md px-3 py-2 text-xs outline-none forced-colors:focus-visible:outline-2 forced-colors:focus-visible:outline-offset-2 forced-colors:focus-visible:outline-solid',
          view === target
            ? 'bg-active text-foreground focus-visible:bg-selected forced-colors:bg-[Highlight] forced-colors:text-[HighlightText] forced-colors:forced-color-adjust-none forced-colors:focus-visible:bg-[Highlight]'
            : 'text-muted-foreground hover:text-soft-foreground focus-visible:bg-hover focus-visible:text-foreground',
        )}
      >
        {target === 'library' ? 'Projects' : 'References'}
      </a>
    ))}
  </nav>
);
