import { useEffect, useRef, useState } from 'react';
import { DotsThree, PencilSimple, PushPin, X } from '@phosphor-icons/react';
import { toast } from 'sonner';
import { usePostHog } from 'posthog-js/react';
import Button from '@/components/Button';
import TextInput from '@/components/TextInput';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from '@/components/Dialog';
import { Menu, MenuContent, MenuItem, MenuTrigger } from '@/components/Menu';
import { PROJECT_NAME_MAX_LENGTH } from '@rivet/core/types/project-library';
import { errorMessage } from '@rivet/core/utils/errorMessage';

interface ProjectCardActionsProps {
  project: { id: string; name: string; pinnedAt?: string | null };
  onRename: (projectId: string, name: string) => Promise<void>;
  onRemove: (projectId: string) => Promise<void>;
  onSetPinned: (projectId: string, isPinned: boolean) => Promise<void>;
}
type ProjectAction = 'rename' | 'remove';

export const ProjectCardActions = ({
  project,
  onRename,
  onRemove,
  onSetPinned,
}: ProjectCardActionsProps) => {
  const posthog = usePostHog();
  const trigger = useRef<HTMLButtonElement>(null);
  const pinTrigger = useRef<HTMLButtonElement>(null);
  const pinFocusTarget = useRef<'button' | 'menu' | null>(null);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isPinSaving, setIsPinSaving] = useState(false);
  const isPinned = Boolean(project.pinnedAt);
  const [action, setAction] = useState<ProjectAction | null>(null);
  const [name, setName] = useState(project.name);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  let submitLabel = action === 'rename' ? 'Save name' : 'Remove from projects';
  if (isSaving) submitLabel = 'Saving…';
  useEffect(() => {
    if (isPinSaving || !pinFocusTarget.current) return;
    const target = pinFocusTarget.current === 'button' ? pinTrigger : trigger;
    pinFocusTarget.current = null;
    target.current?.focus();
  }, [isPinSaving]);
  const changeMenu = (isOpen: boolean) => {
    setIsMenuOpen(isOpen);
    posthog?.capture(
      isOpen ? 'library_project_menu_opened' : 'library_project_menu_closed',
    );
  };
  const togglePin = async (method: 'button' | 'menu') => {
    if (isPinSaving) return;
    pinFocusTarget.current = method;
    setIsPinSaving(true);
    posthog?.capture('library_project_pin_clicked', {
      is_pinning: !isPinned,
      method,
    });
    try {
      await onSetPinned(project.id, !isPinned);
    } catch (failure) {
      toast.error(errorMessage(failure, 'Could not save pin. Try again.'));
    } finally {
      setIsPinSaving(false);
    }
  };
  const chooseAction = (selected: ProjectAction) => {
    setName(project.name);
    setError(null);
    setAction(selected);
    posthog?.capture('library_project_action_opened', { action: selected });
  };
  const closeAction = (outcome: 'cancelled' | 'completed') => {
    posthog?.capture('library_project_action_closed', { action, outcome });
    setAction(null);
  };
  const submit = async () => {
    if (isSaving || !action || (action === 'rename' && !name.trim())) return;
    setIsSaving(true);
    setError(null);
    try {
      if (action === 'rename') await onRename(project.id, name.trim());
      else await onRemove(project.id);
      closeAction('completed');
    } catch (failure) {
      setError(errorMessage(failure, 'Could not save changes. Try again.'));
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <>
      <div
        className={`flex items-center gap-0.5 group-hover/project:pointer-events-auto group-hover/project:opacity-100 has-[:focus-visible]:pointer-events-auto has-[:focus-visible]:opacity-100 [@media(hover:none)]:pointer-events-auto [@media(hover:none)]:opacity-100 ${isMenuOpen ? 'pointer-events-auto opacity-100' : 'pointer-events-none opacity-0'}`}
      >
        <Button
          ref={pinTrigger}
          type="button"
          variant="ghost"
          size="icon-compact"
          title={isPinned ? 'Unpin project' : 'Pin project'}
          aria-label={`${isPinned ? 'Unpin' : 'Pin'} ${project.name}`}
          aria-pressed={isPinned}
          disabled={isPinSaving}
          onClick={() => {
            void togglePin('button');
          }}
        >
          <PushPin weight={isPinned ? 'fill' : 'bold'} size={16} aria-hidden />
        </Button>
        <Menu isOpen={isMenuOpen} onOpenChange={changeMenu}>
          <MenuTrigger asChild>
            <Button
              ref={trigger}
              type="button"
              variant="ghost"
              size="icon-compact"
              aria-label={`Actions for ${project.name}`}
            >
              <DotsThree size={16} weight="bold" aria-hidden />
            </Button>
          </MenuTrigger>
          <MenuContent
            data-rivet-private
            aria-label="Project actions"
            align="start"
            onCloseAutoFocus={(event) => {
              if (action) event.preventDefault();
            }}
            className="ph-no-capture min-w-44"
          >
            <MenuItem
              disabled={isPinSaving}
              onSelect={() => void togglePin('menu')}
            >
              <PushPin
                size={14}
                weight={isPinned ? 'fill' : 'bold'}
                aria-hidden
              />
              {isPinned ? 'Unpin' : 'Pin'}
            </MenuItem>
            <MenuItem onSelect={() => chooseAction('rename')}>
              <PencilSimple size={14} weight="bold" aria-hidden />
              Rename
            </MenuItem>
            <MenuItem onSelect={() => chooseAction('remove')}>
              <X size={14} weight="bold" aria-hidden />
              Remove from projects
            </MenuItem>
          </MenuContent>
        </Menu>
      </div>
      <Dialog
        open={action !== null}
        onOpenChange={(isOpen) => {
          if (!isOpen && !isSaving) closeAction('cancelled');
        }}
      >
        <DialogContent
          surface="library"
          size="sm"
          data-rivet-private
          onCloseAutoFocus={(event) => {
            event.preventDefault();
            trigger.current?.focus();
          }}
          className="ph-no-capture"
        >
          <DialogTitle className="text-base font-medium break-words">
            {action === 'rename'
              ? 'Rename project'
              : `Remove “${project.name}” from projects?`}
          </DialogTitle>
          <DialogDescription className="text-foreground-tertiary mt-2 text-sm leading-6">
            {action === 'rename'
              ? 'Choose a display name for this project. Its folder name will stay the same.'
              : 'Your folders and saved variants will remain on this computer. Open the project again to restore it.'}
          </DialogDescription>
          <form
            onSubmit={(event) => {
              event.preventDefault();
              void submit();
            }}
          >
            {action === 'rename' ? (
              <label className="text-foreground-secondary mt-5 block text-xs">
                Project name
                <TextInput
                  autoFocus
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                  maxLength={PROJECT_NAME_MAX_LENGTH}
                  disabled={isSaving}
                  className="mt-2"
                />
              </label>
            ) : null}
            {error ? (
              <p role="alert" className="text-muted-foreground mt-4 text-xs">
                {error}
              </p>
            ) : null}
            <div className="mt-6 flex justify-end gap-2">
              <Button
                type="button"
                variant="ghost"
                disabled={isSaving}
                onClick={() => closeAction('cancelled')}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                variant="secondary"
                disabled={isSaving || (action === 'rename' && !name.trim())}
              >
                {submitLabel}
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </>
  );
};
