import { fetchLibraryApi } from '@/library/api';

interface ReferenceMediaRequest {
  profileId: string;
  referenceId: string;
  hash: string;
  signal?: AbortSignal;
}

export const readReferenceMedia = async ({
  profileId,
  referenceId,
  hash,
  signal,
}: ReferenceMediaRequest): Promise<Blob> => {
  const response = await fetchLibraryApi(
    `/api/library/profile/references/${encodeURIComponent(referenceId)}/media/${hash}?${new URLSearchParams({ profileId })}`,
    { signal },
  );
  if (!response.ok) throw new Error('Image unavailable');
  return response.blob();
};
